    """Calculate the number of words with a smaller frequency of their lowest character for each query."""
    queries_min_frequencies = [0] * len(queries)
    for i in range(len(queries)):
        queries_min_frequencies[i] = compute_lowest_frequency(queries[i])

    words_min_frequencies = [0] * len(words)
    for i in range(len(words)):
        words_min_frequencies[i] = compute_lowest_frequency(words[i])

